package com.bankingsystem.core.features.transactions;
import com.bankingsystem.core.features.accesscontrol.domain.*;import com.bankingsystem.core.features.accesscontrol.domain.repository.*;import com.bankingsystem.core.features.accounts.domain.*;import com.bankingsystem.core.features.accounts.domain.repository.*;import com.bankingsystem.core.features.auth.domain.*;import com.bankingsystem.core.features.auth.domain.repository.*;import com.bankingsystem.core.features.customer.domain.*;import com.bankingsystem.core.features.customer.domain.repository.*;import com.bankingsystem.core.features.ledger.application.*;import com.bankingsystem.core.features.ledger.domain.*;import com.bankingsystem.core.features.ledger.domain.repository.*;import com.bankingsystem.core.features.transactions.domain.repository.*;import com.bankingsystem.core.features.transactions.idempotency.domain.repository.*;import com.bankingsystem.core.modules.common.enums.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.boot.test.context.*;import org.springframework.security.test.context.support.*;import org.springframework.test.context.*;import org.springframework.test.web.servlet.*;import javax.sql.DataSource;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.http.MediaType.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("dev") class FinancialTransactionApiIntegrationTest {
 @Autowired MockMvc mvc;@Autowired DataSource ds;@Autowired UserRepository users;@Autowired CustomerRepository customers;@Autowired RoleRepository roles;@Autowired AccountRepository accounts;@Autowired LedgerAccountRepository ledgers;@Autowired PostingEngine engine;@Autowired JournalEntryRepository journals;@Autowired TransactionRepository tx;@Autowired CoreTransactionIdempotencyRepository idem; LedgerAccount vault;
 @BeforeEach void clean()throws Exception{try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("SET FOREIGN_KEY_CHECKS=0");for(String t:new String[]{"core_transaction_idempotency","transactions","journal_postings","journal_entries"})s.execute("DELETE FROM "+t);s.execute("DELETE FROM ledger_accounts WHERE customer_account_id IS NOT NULL");s.execute("DELETE FROM accounts");s.execute("DELETE FROM customers WHERE email LIKE '4b9-api-%'");s.execute("DELETE FROM users WHERE email LIKE '4b9-api-%'");s.execute("SET FOREIGN_KEY_CHECKS=1");}vault=ledgers.findBySystemCode("SYSTEM_VAULT_CASH:LKR").orElseGet(()->ledgers.saveAndFlush(new LedgerAccount(UUID.randomUUID(),null,"SYSTEM_VAULT_CASH:LKR",LedgerAccountClass.ASSET,"LKR",LedgerAccountStatus.ACTIVE,LocalDateTime.now())));}
 @Test void unauthenticatedIs401()throws Exception{mvc.perform(post("/api/v1/transactions/deposit").contentType(APPLICATION_JSON).header("Idempotency-Key","x").content("{\"accountId\":\"00000000-0000-0000-0000-000000000001\",\"amount\":\"1.00\"}")).andExpect(status().isUnauthorized());}
 @Test void wrongRoleIs403()throws Exception{mvc.perform(post("/api/v1/transactions/deposit").with(user("x").roles("ADMIN")).contentType(APPLICATION_JSON).header("Idempotency-Key","x").content("{\"accountId\":\"00000000-0000-0000-0000-000000000001\",\"amount\":\"1.00\"}")).andExpect(status().isForbidden());}
 @Test void depositReplayAndConflict()throws Exception{F f=f("alice","100");String b="{\"accountId\":\""+f.a.getAccountId()+"\",\"amount\":\"50.00\"}";var req=post("/api/v1/transactions/deposit").with(user(f.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key","api-1");var x=mvc.perform(req.content(b)).andExpect(status().isOk()).andReturn();long j=journals.count();mvc.perform(req.content(b)).andExpect(status().isOk());assertThat(journals.count()).isEqualTo(j);assertThat(mvc.perform(req.content(b)).andReturn().getResponse().getContentAsString()).contains("\"replayed\":true");mvc.perform(req.content(b.replace("50.00","50.01"))).andExpect(status().isConflict());assertThat(accounts.findById(f.a.getAccountId()).orElseThrow().getBalance()).isEqualByComparingTo("150.0000");}
 @Test void strictInputAndMissingKeyAre400()throws Exception{F f=f("v","0");String p="{\"accountId\":\""+f.a.getAccountId()+"\",\"amount\":\"12.3456\"}";mvc.perform(post("/api/v1/transactions/deposit").with(user(f.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key","s").content(p)).andExpect(status().isUnprocessableEntity());mvc.perform(post("/api/v1/transactions/deposit").with(user(f.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).content(p.replace("12.3456","1.00"))).andExpect(status().isBadRequest());}
 @Test void sourceBolaRejectedAndCrossCustomerDestinationAllowed()throws Exception{F a=f("a","100"),b=f("b","20");String p="{\"sourceAccountId\":\""+a.a.getAccountId()+"\",\"destinationAccountId\":\""+b.a.getAccountId()+"\",\"amount\":\"25.00\"}";mvc.perform(post("/api/v1/transactions/transfer").with(user(b.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key","b").content(p)).andExpect(status().is4xxClientError());mvc.perform(post("/api/v1/transactions/transfer").with(user(a.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key","t").content(p)).andExpect(status().isOk());assertThat(accounts.findById(a.a.getAccountId()).orElseThrow().getBalance()).isEqualByComparingTo("75.0000");}
 @Test void concurrentSameKeyRequestsExecuteOnce() throws Exception { F f=f("conc","0"); String b="{\"accountId\":\""+f.a.getAccountId()+"\",\"amount\":\"10.00\"}"; var pool=java.util.concurrent.Executors.newFixedThreadPool(2); java.util.concurrent.Callable<Integer> call=()->mvc.perform(post("/api/v1/transactions/deposit").with(user(f.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key","conc-key").content(b)).andReturn().getResponse().getStatus(); var a=pool.submit(call);var c=pool.submit(call);assertThat(a.get()).isEqualTo(200);assertThat(c.get()).isEqualTo(200);pool.shutdown();assertThat(accounts.findById(f.a.getAccountId()).orElseThrow().getBalance()).isEqualByComparingTo("10.0000");}
 @Test void concurrentDifferentKeyWithdrawalsPreventOverspend() throws Exception { F f=f("overspend","100"); String b="{\"accountId\":\""+f.a.getAccountId()+"\",\"amount\":\"80.00\"}"; var pool=java.util.concurrent.Executors.newFixedThreadPool(2); var call=(java.util.concurrent.Callable<Integer>)(()->mvc.perform(post("/api/v1/transactions/withdraw").with(user(f.u.getUsername()).roles("CUSTOMER")).contentType(APPLICATION_JSON).header("Idempotency-Key",UUID.randomUUID().toString()).content(b)).andReturn().getResponse().getStatus()); var a=pool.submit(call);var c=pool.submit(call);int x=a.get(),y=c.get();pool.shutdown();assertThat(List.of(x,y)).contains(200).contains(422);assertThat(accounts.findById(f.a.getAccountId()).orElseThrow().getBalance()).isEqualByComparingTo("20.0000");}
 private F f(String n,String initial){Role r=roles.findByRoleNameIgnoreCase("CUSTOMER").orElseGet(()->{Role z=new Role();z.setRoleName("CUSTOMER");z.setDescription("t");return roles.saveAndFlush(z);});String q="4b9-api-"+n+UUID.randomUUID();User u=new User();u.setUsername(q);u.setPasswordHash("x");u.setEmail(q+"@example.test");u.setRole(r);u.setIsActive(true);u.setCreatedAt(LocalDateTime.now());u=users.saveAndFlush(u);Customer c=new Customer();c.setUser(u);c.setFirstName(n);c.setLastName("t");c.setGender(Gender.OTHER);c.setEmail(u.getEmail());c.setPhone("+94770000000");c.setDateOfBirth(LocalDate.of(1990,1,1));c.setStatus(Status.ACTIVE);c=customers.saveAndFlush(c);Account a=new Account();a.setAccountNumber("4B9-"+UUID.randomUUID());a.setAccountType(AccountType.SAVINGS);a.setAccountStatus(AccountStatus.ACTIVE);a.setBalance(new BigDecimal("0.0000"));a.setCurrency("LKR");a.setCustomer(c);a.setCreatedAt(LocalDateTime.now());a.setUpdatedAt(LocalDateTime.now());a=accounts.saveAndFlush(a);LedgerAccount la=ledgers.saveAndFlush(new LedgerAccount(UUID.randomUUID(),a.getAccountId(),null,LedgerAccountClass.LIABILITY,"LKR",LedgerAccountStatus.ACTIVE,LocalDateTime.now()));if(new BigDecimal(initial).signum()>0){var m=MonetaryAmount.fromCustomerInput(initial,CurrencyCode.LKR);engine.post(new PostingCommand(JournalEntryType.DEPOSIT,CurrencyCode.LKR,"seed",PostingActor.system("T"),LedgerChannel.SYSTEM,List.of(new PostingInstruction(vault.getLedgerAccountId(),PostingDirection.DEBIT,m),new PostingInstruction(la.getLedgerAccountId(),PostingDirection.CREDIT,m))));}return new F(u,a);}record F(User u,Account a){}
}
